function deepClone(source, map = new WeakMap()) {
    // 基本类型和 null 直接返回
    if (source === null || typeof source !== 'object') {
        return source;
    }

    // 循环引用：已拷贝过的对象直接返回之前的副本
    if (map.has(source)) {
        return map.get(source);
    }

    // 特殊内置类型：按构造器重建
    if (source instanceof Date) {
        return new Date(source.getTime());
    }
    if (source instanceof RegExp) {
        return new RegExp(source.source, source.flags);
    }
    if (source instanceof Map) {
        const mapCopy = new Map();
        map.set(source, mapCopy);            // 先注册，再递归
        source.forEach((val, key) => {
            mapCopy.set(deepClone(key, map), deepClone(val, map));
        });
        return mapCopy;
    }
    if (source instanceof Set) {
        const setCopy = new Set();
        map.set(source, setCopy);
        source.forEach(val => {
            setCopy.add(deepClone(val, map));
        });
        return setCopy;
    }

    // 数组和普通对象
    const target = Array.isArray(source) ? [] : Object.create(Object.getPrototypeOf(source));
    map.set(source, target);                // 先注册到 map，再递归属性

    for (const key of Reflect.ownKeys(source)) {
        const desc = Object.getOwnPropertyDescriptor(source, key);
        if (desc.value !== undefined) {
            desc.value = deepClone(desc.value, map);
        }
        Object.defineProperty(target, key, desc);
    }
    return target;
}

// --- 使用示例 ---
const obj = {
    name: 'Alice',
    birthday: new Date('1995-06-15'),
    skills: new Set(['JS', 'TS']),
    meta: new Map([['level', 3]]),
};
obj.self = obj;  // 循环引用

const copy = deepClone(obj);
console.log(copy.birthday instanceof Date);   // true
console.log(copy.skills instanceof Set);      // true
console.log(copy.self === copy);              // true（循环引用被正确处理）
console.log(copy === obj);                    // false（完全独立）
